"use client";

import { AnimatePresence, motion, useReducedMotion, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, useState } from "react";

import { cn } from "@/lib/utils";

/** Props for a row of steps. Pass `current` to control it, or `defaultCurrent` to let it hold its own state. */
export type StepProgressProps = Omit<ComponentPropsWithoutRef<"div">, "children"> & {
  /** The step names, in order. Keep each to one or two words. */
  steps: string[];
  /** The index of the step the person is on, from 0. Every step before it shows as finished. */
  current?: number;
  defaultCurrent?: number;
  onCurrentChange?: (current: number) => void;
  /** Names the list for screen readers, for example "Checkout". */
  label?: string;
  backLabel?: string;
  nextLabel?: string;
};

// Damping 35 is 2 × √300, rounded up: critically damped, so the line fills without overshoot.
const FILL: Transition = { type: "spring", stiffness: 300, damping: 35, mass: 1 };
const SWAP: Transition = { duration: 0.2, ease: [0.165, 0.84, 0.44, 1] };
const FADE: Transition = { duration: 0.15 };
const INSTANT: Transition = { duration: 0 };

const NAV_BUTTON =
  "inline-flex min-h-11 cursor-pointer touch-manipulation items-center rounded-full px-4 text-sm font-medium outline-none active:scale-97 aria-disabled:cursor-not-allowed aria-disabled:opacity-50 aria-disabled:active:scale-100 focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background motion-safe:transition motion-safe:duration-150 sm:min-h-9";

function CheckGlyph() {
  return (
    <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true" className="size-4">
      <path d="m3.5 8.5 3 3 6-6.5" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

/**
 * Shows where the person is in a short flow, with Back and Next. The line
 * to the next step fills as they move on, and a finished step turns into a check.
 */
export function StepProgress({
  steps,
  current,
  defaultCurrent = 0,
  onCurrentChange,
  label = "Progress",
  backLabel = "Back",
  nextLabel = "Next",
  className,
  ...divProps
}: StepProgressProps) {
  const [ownCurrent, setOwnCurrent] = useState(defaultCurrent);
  const last = Math.max(steps.length - 1, 0);
  // A parent can pass a shorter list or a stale index, so never point past either end.
  const at = Math.min(Math.max(current ?? ownCurrent, 0), last);
  const reduceMotion = useReducedMotion();
  const hidden = reduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.6, filter: "blur(0.25rem)" };

  const go = (next: number) => {
    if (next < 0 || next > last) return;
    if (current === undefined) setOwnCurrent(next);
    onCurrentChange?.(next);
  };

  return (
    <div {...divProps} className={cn("flex w-full max-w-sm flex-col gap-6", className)}>
      <ol aria-label={label} className="flex">
        {steps.map((step, index) => {
          const done = index < at;
          const isCurrent = index === at;
          return (
            <li key={step} aria-current={isCurrent ? "step" : undefined} className="relative flex flex-1 flex-col items-center gap-2">
              {index < last ? (
                // The line runs from the middle of this circle to the middle of the next one, under both.
                <span aria-hidden="true" className="absolute top-4 left-1/2 h-0.5 w-full -translate-y-1/2 bg-border">
                  <motion.span
                    initial={false}
                    animate={{ scaleX: done ? 1 : 0 }}
                    transition={reduceMotion ? INSTANT : FILL}
                    className="block size-full origin-left bg-primary"
                  />
                </span>
              ) : null}
              <span
                className={cn(
                  "relative grid size-8 place-items-center rounded-full border-2 text-sm font-medium tabular-nums motion-safe:transition-colors motion-safe:duration-200",
                  done && "border-primary bg-primary text-primary-foreground",
                  // The current step is a ring around a filled centre, so it differs from the others in shape as well as colour.
                  isCurrent && "border-primary bg-background text-foreground ring-2 ring-primary ring-offset-2 ring-offset-background",
                  !done && !isCurrent && "border-border bg-background text-muted-foreground",
                )}
              >
                <AnimatePresence mode="popLayout" initial={false}>
                  <motion.span
                    key={done ? "check" : "number"}
                    aria-hidden="true"
                    initial={hidden}
                    animate={{ opacity: 1, scale: 1, filter: "blur(0rem)" }}
                    exit={hidden}
                    transition={reduceMotion ? FADE : SWAP}
                    className="col-start-1 row-start-1 flex"
                  >
                    {done ? <CheckGlyph /> : index + 1}
                  </motion.span>
                </AnimatePresence>
              </span>
              <span className={cn("text-center text-sm", isCurrent ? "font-medium text-foreground" : "text-muted-foreground")}>
                <span className="sr-only">{done ? "Finished: " : `Step ${index + 1}: `}</span>
                {step}
              </span>
            </li>
          );
        })}
      </ol>
      <p role="status" className="sr-only">
        Step {at + 1} of {steps.length}: {steps[at]}
      </p>
      <div className="flex items-center justify-between gap-3">
        {/* The buttons stay focusable at either end: a disabled button would drop keyboard focus. */}
        <button
          type="button"
          aria-disabled={at === 0 || undefined}
          onClick={() => go(at - 1)}
          className={cn(NAV_BUTTON, "border border-border bg-background text-foreground hover:bg-muted")}
        >
          {backLabel}
        </button>
        <button
          type="button"
          aria-disabled={at === last || undefined}
          onClick={() => go(at + 1)}
          className={cn(NAV_BUTTON, "bg-primary text-primary-foreground")}
        >
          {nextLabel}
        </button>
      </div>
    </div>
  );
}
